  const shape = (d, fill, extra = '') => `<path d="${d}" fill="${fill}" stroke="${L}" stroke-width="${sw}" stroke-linejoin="round" stroke-linecap="round" ${extra}/>`;
  const line = (d, color = L, w = 1.6, op = 1) => `<path d="${d}" fill="none" stroke="${color}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round" opacity="${op}"/>`;
  const leaf = (x, y, r, s, c, d = 0) => `<g class="c-leaf" style="animation-delay:${d}s"><g transform="translate(${x} ${y}) rotate(${r}) scale(${s})"><path d="M0,0 C3,-6 11,-7 16,-4 C12,2 5,4 0,0Z" fill="${c}" stroke="${L}" stroke-width="1.3" stroke-linejoin="round"/><path d="M1.5,-0.6 C6,-2.4 10,-3.2 13,-3.6" fill="none" stroke="${L}" stroke-width=".9" stroke-linecap="round" opacity=".7"/></g></g>`;
  const dot = (x, y, r, c, d = 0) => `<circle class="c-spark" style="animation-delay:${d}s" cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
