  const foot = (x, y, rot, flip = false) => `<g transform="translate(${x} ${y}) rotate(${rot}) scale(${flip ? -1 : 1} 1)">${shape('M8,-6 C2,-7 -8,-5 -14,-1 C-18,2 -16,6 -10,6 L8,6 C12,3 12,-4 8,-6Z', 'var(--skin)')}${line('M-12,1 L-12.5,4 M-9,1.5 L-9.4,4.6 M-6,2 L-6.2,5', L, .9, .6)}</g>`;
